const FLORA_ISSUES=[
{id:'stress',name:'Студ, суша, слънчев пригор или преовлажняване',type:'Условия',signs:'Кафяви краища, увяхване или пожълтяване след жега, мраз, пресаждане или промяна на поливането. Липсва задължително налеп или видим неприятел.',confusion:'Същите признаци може да са от коренова болест. Есенен листопад, летният покой на дицентрата и сортовите пъстри листа могат да са нормални.',steps:['Сравни здрави и засегнати растения; виж дали проблемът следва изложение, поливна зона или дата на резитба.','Провери почвената влага и оттичането, кореновата шийка и скорошните обработки.','Коригирай доказаната причина и наблюдавай новия прираст; не добавяй тор или препарат на сляпо.'],escalate:'При бързо загиване, мокра гниеща основа или разпространение към съседни растения — диагностика на място.',products:[],url:'https://www.rhs.org.uk/problems/conifers-brown-patches'},
{id:'mildew',name:'Брашнеста мана',type:'Болест',signs:'Бял до сив брашнест налеп върху листа/връхчета; възможна деформация и отслабване.',confusion:'Варовикови следи от вода или естествени сребристи петна не са доказателство за мана.',steps:['Огледай новите листа и двете им страни; документирай разпространението.','Отстрани силно засегнатите части и подобри проветрението, без да пресушаваш корените.','Избягвай прекомерен азот. За химична намеса трябва потвърдена култура и точна разрешена употреба.'],escalate:'При силно нападение или неясен налеп потърси агроном; препарат за едно цвете не покрива всички видове.',products:['topaz'],url:'https://www.rhs.org.uk/disease/powdery-mildews'},
{id:'graymold',name:'Сиво гниене / Botrytis',type:'Болест',signs:'Меки кафяви цветове/листа, загниваща тъкан и сив пухкав налеп, особено при влажност и слабо движение на въздуха.',confusion:'Изгорели сухи цветове без налеп не доказват Botrytis. Кореново гниене изисква друга оценка.',steps:['Отдели силно засегнатите растения и събери гниещите цветове, без да ги разтърсваш из лехата.','Намали продължителното мокрене на листата, разреди прекалено гъстия посев и поливай почвата сутрин при нужда.','Почисти инструментите и наблюдавай новия прираст; провери ограниченията за чувствителни видове.'],escalate:'При загниване на основата или масово загиване — оглед и диагноза преди третиране.',products:['switch'],url:'https://www.rhs.org.uk/disease/grey-mould'},
{id:'rootrot',name:'Кореново/шийково гниене; съмнение за Phytophthora',type:'Болест / условия',signs:'Увяхване въпреки мократа почва, губене на зелен цвят, загиване на клони; корени кафяви и разпадащи се вместо здрави и твърди.',confusion:'Суша, прекалено дълбоко засаждане и други коренови патогени имат сходни признаци. По листата не се определя надеждно причинителят.',steps:['Провери влагата, оттичането и кореновата шийка; не увеличавай водата автоматично.','Отдели съмнителните растения и не пренасяй почва/отток към здрави лехи.','При силно загниване поискай лабораторна или агрономическа оценка; подобри оттичането преди презасаждане.'],escalate:'Не поливай с произволен фунгицид. Няма потвърдена универсална химична схема в този справочник.',products:[],url:'https://www.rhs.org.uk/disease/phytophthora-root-rot'},
{id:'tipblight',name:'Съхнене на иглолистни връхчета / Pestalotiopsis',type:'Болест',signs:'Огнища от кафяви връхчета; възможни дребни черни плодни телца по мъртвата тъкан. Често при предварително стресирани растения.',confusion:'Кипарисови въшки, мраз, суша и рязане до стара дървесина могат да изглеждат подобно.',steps:['Огледай клонките отблизо и провери за живи въшки, нараняване и воден стрес.','Изрежи доказано мъртвите части при сухо време и почиствай инструмента между растенията.','Подобри влагата и проветрението; не компенсирай повредите с прекомерно торене.'],escalate:'При повтарящо се съхнене вземи проба; точната причина може да изисква лаборатория.',products:[],url:'https://www.rhs.org.uk/disease/conifers-pestalotiopsis-disease'},
{id:'canker',name:'Рак/язви по кипарисови клони',type:'Болест',signs:'Единични жълтеещи и кафяви клони, хлътнали или напукани участъци по кората и смолотечение. Възможно пръстеновидно загиване.',confusion:'Повредена кора или смола сама по себе си не доказва конкретна гъба.',steps:['Проследи сухия клон към основата и документирай язвата; избягвай допълнителни рани.','Премахвай засегнати малки клони до здрава тъкан при сухо време с чист инструмент.','Намали водния стрес. При стволови язви и големи клони потърси специалист, вместо силна самостоятелна резитба.'],escalate:'Фунгицид не възстановява вече загинала кора. Не е включено непотвърдено „лечение“ с препарат.',products:[],url:'https://ipm.ucanr.edu/home-and-landscape/cypress-canker/'},
{id:'leafspot',name:'Листни петна — гъбни или бактериални',type:'Нужна диагноза',signs:'Нарастващи кафяви/черни петна, понякога с ореол, изсъхващ център или отпадане на листата.',confusion:'Пригор, пръски от препарат, хранителен проблем и естествена окраска могат да имитират петносване.',steps:['Снимай двете страни на листа, здрав и болен прираст и разположението в лехата.','Отделяй силно болните листа; не работи първо с мокрите болни растения и после със здравите.','Намали дългото мокрене на листата и провери въздуха/оттичането. Не избирай фунгицид само по цвят на петното.'],escalate:'Воднисти петна, бързо увяхване или разпространение — агроном. При съмнение за бактерия листен фунгицид може да е неподходящ.',products:[],url:'https://www.rhs.org.uk/prevention-protection/preventing-pest-and-disease-problems'},
{id:'rust',name:'Ръжда по листата, включително по мушкато',type:'Болест',signs:'Жълтеникави петна отгоре и прашливи ръждивокафяви пустули отдолу; при зонално мушкато може да са в концентрични кръгове.',confusion:'Механична драскотина или сух пригор не образуват типични спорови пустули. Различните ръжди имат различни гостоприемници.',steps:['Отдели растението от здравите, особено преди прибиране за зимуване.','Махни засегнатите листа, избягвай мокрене и подобри проветрението.','Не вземай резници от заразено растение; химична употреба само за изрично покрити растения.'],escalate:'За други видове ръжда не пренасяй автоматично схемата за Pelargonium.',products:['topaz'],url:'https://www.rhs.org.uk/disease/pelargonium-rust'},
{id:'heuchera-rust',name:'Ръжда по хойхера',type:'Болест',signs:'Вдлъбнати петънца отгоре, а отдолу — повдигнати кафяво-оранжеви пустули; листата могат да се деформират.',confusion:'Нормалната пурпурна или сребриста листна окраска е равномерна сортова особеност, без спорови възглавнички.',steps:['Премахни болните листа и събери отпадъците отделно.','Разреди гъсти туфи и поливай почвата вместо листата.','При нови симптоми по следващия прираст потърси потвърждение на причината.'],escalate:'Топаз не е предложен за хойхера: не е потвърдена такава конкретна употреба.',products:[],url:'https://www.rhs.org.uk/disease/heuchera-rust'},
{id:'aphids',name:'Листни въшки',type:'Неприятел',signs:'Колонии по младите върхове/пъпки, завити листа, лепкав меден сок, бели съблекла и понякога чернилни налепи.',confusion:'Чернилният налеп може да е следствие от смучещи насекоми, а не първична листна гъбна болест.',steps:['Огледай живите колонии с лупа; различи ги от съблекла и полезни хищници.','При ограничено нападение премахни засегнатия връх или отмий внимателно колонията, ако растението го понася.','Наблюдавай калинки и други естествени неприятели; химичен избор само при установен вид и необходимост.'],escalate:'Намереният етикет на Децис за декоративни е за Myzus spp., а не за всяка листна въшка.',products:['decis'],url:'https://www.rhs.org.uk/biodiversity/aphids'},
{id:'conifer-aphid',name:'Кипарисови листни въшки / Cinara',type:'Неприятел',signs:'Живи кафеникави въшки по вътрешни клонки; лепкав секрет, чернилни налепи и по-късно кафяви петна по плета.',confusion:'Суша, резитба, Pestalotiopsis и ракови язви също причиняват кафяви петна.',steps:['Разтвори клонките и търси живи насекоми; не пръскай само заради стара кафява тъкан.','Оцени водния стрес и запиши разпространението със снимки.','За силно нападение поискай препарат с изрична българска употреба за установения неприятел върху конкретния плет.'],escalate:'Децис за Myzus не е автоматична препоръка за Cinara. Тук не е потвърден химичен продукт за този случай.',products:[],url:'https://www.rhs.org.uk/biodiversity/cypress-aphid'},
{id:'mites',name:'Паяжинообразуващи акари',type:'Неприятел',signs:'Ситни светли точици, бронзиране и фина паяжина; дребни подвижни акари и яйца отдолу. Обикновено се усилва в жега и сухота.',confusion:'Не всеки паяк върху растение е вредител. Трипси и хранителни проблеми могат да причинят сходно обезцветяване.',steps:['Огледай долната страна с лупа и потупай над бял лист.','Отдели силно засегнатите саксии и намали доказания воден стрес.','Потърси биологичен контрол или конкретно разрешен акарицид; обикновен инсектицид не е равнозначен на акарицид.'],escalate:'Не е включена непотвърдена схема с акарицид за всички 34 растения.',products:[],url:'https://www.rhs.org.uk/biodiversity/glasshouse-red-spider-mite'},
{id:'thrips',name:'Трипси',type:'Неприятел',signs:'Сребристи драскотини, дребни черни точици, деформирани пъпки; тесни подвижни насекоми при изтръскване над бяло.',confusion:'Повреда от акари или пръскане не се доказва като трипс само по сребристия цвят.',steps:['Огледай цветовете с лупа и потупай над бяла хартия.','Почисти силно засегнатите цветове и отдели новозакупени заразени растения.','Използвай уловки за наблюдение; химичният вариант в справочника е само за потвърден Thrips tabaci.'],escalate:'Калифорнийският трипс не се приравнява автоматично на тютюнев трипс за целите на етикета.',products:['decis'],url:'https://www.rhs.org.uk/biodiversity/thrips'},
{id:'whitefly',name:'Оранжерийна белокрилка',type:'Неприятел',signs:'Дребни бели крилати насекоми излитат при раздвижване; плоски нимфи отдолу, лепкав сок и чернилни налепи.',confusion:'Белите съблекла на въшки не излитат. Не всички белокрилки са Trialeurodes vaporariorum.',steps:['Провери долната страна и идентифицирай вида, особено при прибиране на мушката.', 'Отдели засегнатите саксии и следи с жълти уловки; при подходящи защитени условия прецени биоконтрол.','При химична намеса спази конкретния гостоприемник, вид, категория и условия на етикета.'],escalate:'Не използвай употреба само за закрито като разрешение за външен двор.',products:['decis'],url:'https://www.rhs.org.uk/biodiversity/glasshouse-whitefly'},
{id:'slugs',name:'Голи охлюви и охлюви',type:'Неприятел',signs:'Неравни дупки, изядени млади листа и пъпки; възможни лъскави следи от слуз, често нощем.',confusion:'Нагризване от гъсеници и хоботници изисква друг контрол; липсата на слуз не изключва охлюви.',steps:['Огледай привечер и под укрития, особено около хости и млад разсад.','Събирай видимите охлюви и намали излишните влажни укрития около уязвимите растения.','При нужда използвай конкретно разрешена примамка по площта от етикета, не на купчинки.'],escalate:'Пази достъпа на деца/животни и водоеми според етикета; „нисък риск“ не означава произволна употреба.',products:['ironmax'],url:'https://www.rhs.org.uk/biodiversity/slugs-and-snails'},
{id:'weevil',name:'Лозов/набразден хоботник',type:'Неприятел',signs:'Дъговидно нагризан листен ръб; при корените — светли извити ларви с кафява глава. Може внезапно да увехне цялата туфа.',confusion:'Възрастните и ларвите увреждат различни части. Само дупки по листата не доказват ларвна повреда.',steps:['Огледай нощем за възрастни, а саксията/корените — за ларви.','Изолирай нападнатите саксии и не мести заразен субстрат.','За биоконтрол с подходящи ентомопатогенни нематоди спази температурата и влагата на конкретния продукт.'],escalate:'Не е потвърден универсален почвен инсектицид за тези декоративни видове.',products:[],url:'https://www.rhs.org.uk/biodiversity/vine-weevil'},
{id:'scale',name:'Щитоносни въшки — съмнение',type:'Неприятел',signs:'Прикрепени щитчета по листа/стъбла, пожълтяване; някои видове отделят лепкав секрет.',confusion:'Естествени люспи по кората или засъхнал секрет не доказват жив неприятел.',steps:['Огледай с лупа за живи форми и определи вида.','Отдели засегнатите саксии; при малко нападение почисти внимателно, ако растението го понася.','Потърси подходящо разрешено решение за конкретния вид и стадий.'],escalate:'Препарат за листни въшки не е автоматично решение за щитоносни.',products:[],url:'https://plants.ces.ncsu.edu/plants/taxus-baccata/'},
{id:'impatiens-mildew',name:'Мана по Impatiens walleriana',type:'Болест',signs:'Пожълтели листа, бял налеп отдолу, окапване на листа/цветове и оставащи голи стъбла.',confusion:'Това е различно от брашнеста мана; увяхване в горещина само по себе си не я доказва.',steps:['Отдели съмнителните растения и документирай долната страна на листата.','Премахни силно болните растения и отпадъци от лехата; не ги размножавай.','Намали продължителното мокрене; обсъди замяна с подходящ по-устойчив посадъчен материал.'],escalate:'Няма предложена химична схема. Суич не се използва върху Impatiens според намерения етикет.',products:[],url:'https://www.rhs.org.uk/disease/impatiens-downy-mildew'},
{id:'hellebore-black',name:'Черни мрежести ивици по кукуряк',type:'Подозрение за вирус',signs:'Черни мрежести линии/ивици, изоставане в растежа и деформирани нови листа; възможен „black death“.',confusion:'Отделни гъбни петна или старо измръзнало листо не доказват вирус.',steps:['Отдели растението и не вземай резници или деленки.','Потърси потвърждение; при потвърден вирус болното растение се отстранява.','Следи съседните растения и почисти инструментите.'],escalate:'Фунгицидите не лекуват вируса.',products:[],url:'https://www.rhs.org.uk/disease/hellebore-black-death'},
{id:'stemblight',name:'Пригор и гниене на почвопокривни стъбла',type:'Нужна диагноза',signs:'Кафяви петна, съхнещи участъци и загиващи стъбла в плътен килим от винка или пахизандра.',confusion:'Воден стрес и кореново гниене може да дадат същата картина; не определяй Volutella или друг патоген само по обща снимка.',steps:['Огледай основата и границата между здрава и болна тъкан.','Изрежи и изнеси болните части; разреди за въздух и избягвай постоянно мокри листа.','Проследи разширяването; при ново загиване вземи проба за диагноза.'],escalate:'Няма потвърдена химична употреба за този неуточнен причинител.',products:[],url:'https://plants.ces.ncsu.edu/plants/pachysandra-terminalis/'},
{id:'abnormal-growth',name:'Мозайка или необичайно деформиран растеж',type:'Нужна диагноза',signs:'Необичайни зелени/жълти ивици, деформирани цветове или израстване на листчета в цветната глава.',confusion:'Сортова пъстрота, акари, препаратен пригор и хранителни проблеми също променят външния вид. Няма автоматична диагноза по цвят.',steps:['Сравни със здраво растение от същия сорт и снимай новия прираст.','Не размножавай и не мести съмнителни растения между обекти.','При трайна деформация потърси агроном/лаборатория; премахване след установяване на причината.'],escalate:'Случаите с вирус или фитоплазма не се „излекуват“ с произволен фунгицид.',products:[],url:'https://plants.ces.ncsu.edu/plants/echinacea-purpurea/'}
];
const FLORA_REGISTRY='https://bfsa.egov.bg/wps/portal/bfsa-web/registers/plant.protection.products';
const FLORA_PRODUCTS=[
{id:'topaz',name:'Топаз 100 ЕК',active:'Пенконазол 100 g/l',category:'Непрофесионална',scope:'За брашнеста мана/ръжди върху изрично посочените декоративни: бегония, далия, невен, хризантема и мушкато. Тук се свързва само с бегония и мушкато.',plants:['begonia','pelargonium'],issues:['mildew','rust'],uses:[{target:'Посочените декоративни; листно при първи признаци',dose:'50 ml/дка = 5 ml за 100 m²',water:'15–100 l работен разтвор/дка, съобразен с калибрирането',limits:'На открито: до 2 приложения, през 10 дни; в оранжерия: до 4, през 7 дни — по намерения етикет.'}],method:'Резервоарът се пълни наполовина, добавя се отмереният продукт при разбъркване, после останалата вода. Не прави непроверени смеси.',caution:'Защитни ръкавици, облекло и очила/лице според етикета. Не пренасяй дозата към туя, хойхера или други непосочени видове.',status:'Прегледани български етикет и страница на Syngenta; действащият регистров статус на 08.11.2026 не е независимо потвърден.',url:'https://agropal-bg.com/documents/2016/06/%D0%95%D0%A2%D0%98%D0%9A%D0%95%D0%A2-%D0%A2%D0%9E%D0%9F%D0%90%D0%97.pdf',supplier:'https://www.syngenta.bg/rastitelna-zashtita/fungicidi/topaz'},
{id:'switch',name:'Суич 62,5 ВГ',active:'Ципродинил 375 g/kg + флудиоксонил 250 g/kg',category:'Втора професионална',scope:'Цветя и зелени декоративни растения срещу сиво гниене. Не е схема за Phytophthora, вируси или ракови язви. Не се пренася към градински дървесен плет от употреба за разсадник/гора.',groups:['sun','partial','shade'],exclude:['impatiens'],issues:['graymold'],uses:[{target:'Допустимите цветя/зелени декоративни при сиво гниене',dose:'96 g/дка = 9,6 g за 100 m²',water:'50–120 l работен разтвор/дка',limits:'Етикет 2021: до 3 през 10–14 дни, за бегония до 2. Производителската страница съдържа и общо ограничение 2 за сезон: текущият максимум не е изяснен. Не планирай повторение без актуален етикет/агроном.'}],method:'Добавя се отмереното количество към около 1/3 вода при разбъркване; долива се. Поддържа се равномерна суспензия.',caution:'Намереният етикет забранява употреба върху Impatiens и тинтява. Само при необходимата правоспособност и с пълните предпазни мерки от етикета.',status:'Прегледани етикет 2021 и производителска страница 2025; регистровият статус и последващите изменения не са независимо потвърдени.',url:'https://agropal-bg.com/documents/2019/06/%D0%95%D1%82%D0%B8%D0%BA%D0%B5%D1%82-%D0%A1%D1%83%D0%B8%D1%87-625-%D0%92%D0%93-2021.pdf',supplier:'https://www.syngenta.bg/rastitelna-zashtita/fungicidi/switch'},
{id:'decis',name:'Децис 100 ЕК',active:'Делтаметрин 100 g/l',category:'Втора професионална',scope:'Декоративни на открито/в оранжерия, само за изброените неприятели. Не е акарицид; не е автоматично решение за кипарисова въшка Cinara.',groups:['hedge','sun','partial','shade'],issues:['aphids','thrips','whitefly'],uses:[{target:'Myzus spp. / тютюнев трипс Thrips tabaci',dose:'6,25–12,5 ml/дка',water:'50–100 l/дка',limits:'До 3 приложения; интервал 7 дни.'},{target:'Оранжерийна белокрилка Trialeurodes vaporariorum',dose:'12,3 ml/дка',water:'50–100 l/дка',limits:'До 3 приложения; интервал 7 дни.'}],method:'Листно при поява и установен целеви неприятел; необходимо е равномерно покритие. Измервай с прецизен мерителен инструмент.',caution:'Етикет 2026, разрешение издание 4/18.06.2025. Професионален продукт: следвай изискванията за оператор, защита, отстояния, достъп и опрашители.',status:'Етикет 2026 е прегледан; отсъствието на последващо отнемане/промяна в регистъра не е независимо потвърдено.',url:'https://agropal-bg.com/documents/2016/06/Label_Decis_100-EC_2026-1-1.pdf',supplier:'https://agropal-bg.com/site/post/?id=3748'},
{id:'ironmax',name:'Айрънмакс Про',active:'Железен фосфат 24,2 g/kg',category:'Непрофесионална',scope:'Голи охлюви и охлюви по неядливи култури; примамка, готова за употреба.',groups:['hedge','sun','partial','shade'],issues:['slugs'],uses:[{target:'Неядливи култури при нападение',dose:'700 g/дка = 0,7 g/m² = 70 g за 100 m²',water:'Не се разрежда с вода.',limits:'Заповедта от 09.04.2024 посочва 1–4 приложения; срокът за повторение се сверява с актуалния етикет.'}],method:'Разпръсква се равномерно по почвената повърхност, не върху растителните части и не на купчини.',caution:'Ръкавици и работно облекло; заповедта изисква 5 m нетретирана зона до повърхностни води. Пази деца и животни според етикета.',status:'Намерена е заповед РД11-919/09.04.2024 с посочен срок до 31.12.2031; последващи промени не са независимо проверени в регистъра.',url:'https://agropal-bg.com/documents/2024/04/%D0%97%D0%90%D0%9F%D0%9E%D0%92%D0%95%D0%94-%D0%90%D0%99%D0%A0%D0%AA%D0%9D%D0%9C%D0%90%D0%9A%D0%A1-%C2%AE-%D0%9F%D0%A0%D0%9E-09.04.2024.pdf',supplier:'https://agropal-bg.com/site/post/?id=22055'}
];
function floraFind(id){return FLORA_PLANTS.find(p=>p.id===id)}
function floraProductMatches(product,plant,issue){if(issue&&!product.issues.includes(issue))return false;if(!plant)return true;return !product.exclude?.includes(plant.id)&&(product.plants?product.plants.includes(plant.id):product.groups?.includes(plant.group))}
function floraLink(url,label){return `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`}
function floraControls(){return `<div class="flora-tools"><input id="flora-search" type="search" class="search" value="${esc(state.floraSearch||'')}" placeholder="Име, латинско име или признак…" aria-label="Търси растение"><label class="field">Изложение / група<select id="flora-group"><option value="">Всички · 34 растения</option>${Object.entries(FLORA_GROUPS).map(([k,n])=>`<option value="${k}" ${state.floraGroup===k?'selected':''}>${n}</option>`).join('')}</select></label></div>`}
function floraPlantsView(){const q=(state.floraSearch||'').toLocaleLowerCase('bg'),rows=FLORA_PLANTS.filter(p=>(!state.floraGroup||p.group===state.floraGroup)&&[p.name,p.latin,p.look,p.bloom,p.winter].join(' ').toLocaleLowerCase('bg').includes(q));return `${floraControls()}<details class="card flora-help"><summary>Подбор за София · как да използваш списъка</summary><p>Практичен подбор за озеленяване, а не класация по продажби. Полусянка означава утринна/разсеяна светлина; сянка не означава тъмно място без светлина. Има и цъфтящи почвопокривни/листнодекоративни растения.</p><p>В картите е отбелязано кое зимува и кое е сезонно. За нови насаждения, ветровити места и саксии провери сорта, микроклимата и дренажа. Цъфтежът е ориентировъчен.</p></details><p>${rows.length} от 34 растения · текстът работи офлайн</p><div class="card">${rows.map(p=>`<button class="list-row" data-action="flora-plant" data-id="${p.id}"><div class="avatar">${icon('leaf')}</div><div class="grow"><strong>${esc(p.name)}</strong><small>${esc(p.latin)}<br>${esc(FLORA_GROUPS[p.group].split(' · ')[0])} · ${esc(p.winter)}</small></div>${icon('chevron')}</button>`).join('')||empty('Няма съвпадения. Опитай друго име или признак.')}</div>`}
function floraProductNotice(){return `<div class="notice"><strong>Преди химична намеса</strong><p>Потвърди растението, причината и точната разрешена употреба в България. Справочните дози не са универсална рецепта за резервоар. Прочети актуалния етикет на закупената опаковка, категорията, защита на оператора, опрашителите и водите, достъпа на хора/животни и срока за повторение.</p><p>Преглед на източниците: ${FLORA_DATE}. Регистърът на БАБХ не предостави данни при проверката; текущият статус не е независимо потвърден. Онлайн обява не доказва разрешение или наличност.</p>${floraLink(FLORA_REGISTRY,'Провери в регистъра на БАБХ')}</div>`}
function floraIssuesView(){const q=(state.issueSearch||'').toLocaleLowerCase('bg'),rows=FLORA_ISSUES.filter(i=>(i.name+' '+i.type+' '+i.signs).toLocaleLowerCase('bg').includes(q)),products=state.floraTopic==='products';return `<div class="tabs flora-switch"><button data-action="flora-topic" data-value="issues" class="${!products?'active':''}">Признаци · 21</button><button data-action="flora-topic" data-value="products" class="${products?'active':''}">Препарати · 4</button></div>${products?`${floraProductNotice()}<div class="card">${FLORA_PRODUCTS.map(p=>`<button class="list-row" data-action="flora-product" data-id="${p.id}"><div class="grow"><strong>${esc(p.name)}</strong><small>${esc(p.active)} · ${esc(p.category)}</small></div>${icon('chevron')}</button>`).join('')}</div>`:`<input id="issue-search" type="search" class="search" value="${esc(state.issueSearch||'')}" placeholder="Например: бял налеп, дупки, кафяви клони…" aria-label="Търси проблем"><p class="muted">Ориентир за оглед, не автоматична диагноза. Не третирай профилактично на сляпо.</p><div class="card">${rows.map(i=>`<button class="list-row" data-action="flora-issue" data-id="${i.id}"><div class="grow"><strong>${esc(i.name)}</strong><small>${esc(i.type)} · ${esc(i.signs)}</small></div>${icon('chevron')}</button>`).join('')||empty('Няма съвпадения.')}</div>`}`}

function openFloraPlant(id){const p=floraFind(id);if(!p)return;modal(p.name,`<p class="muted">${esc(p.latin)} · ${esc(FLORA_GROUPS[p.group].split(' · ')[0])}</p><h3>Как изглежда здравото растение</h3><p>${esc(p.look)}</p><p><strong>Сезон:</strong> ${esc(p.bloom)}</p><div class="notice"><strong>София / зимуване:</strong> ${esc(p.winter)}${p.note?`<p>${esc(p.note)}</p>`:''}</div><h3>Грижи на обекта</h3><ol class="guide-steps">${p.care.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><h3>Възможни проблеми — оглед и мерки</h3><p class="muted">Това са възможности за проверка, не диагноза за всяко растение.</p><div class="flora-problems">${p.issues.map(id=>{const i=FLORA_ISSUES.find(i=>i.id===id);return btn(i.name,'flora-issue','visit','secondary wide',`data-id="${id}" data-plant="${p.id}"`)}).join('')}</div>${btn('Работен дневник за това растение','flora-work','plus','primary wide',`data-id="${p.id}"`)}<div class="guide-sources"><small>Ботанически източник · ${FLORA_DATE}. Снимките за сравнение са във външната страница и изискват интернет; няма разпознаване по камера.</small>${floraLink(p.url,'Описание и снимки за сравнение — NC State / RHS')}</div>`)}
function openFloraIssue(id,plantId=''){const i=FLORA_ISSUES.find(i=>i.id===id),plant=floraFind(plantId);if(!i)return;const products=FLORA_PRODUCTS.filter(p=>i.products.includes(p.id)&&floraProductMatches(p,plant,i.id));modal(i.name,`${plant?`<p class="muted">Оглед за: ${esc(plant.name)}</p>`:''}<p>${badge(i.type)}</p><h3>Признаци</h3><p>${esc(i.signs)}</p><h3>С какво може да се обърка</h3><p>${esc(i.confusion)}</p><h3>Първи мерки</h3><ol class="guide-steps">${i.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="notice">${esc(i.escalate)}</div><h3>Химични варианти само за сверяване</h3>${products.length?`<p class="muted">Провери точния вид неприятел, етикета и актуалния статус преди употреба.</p>${products.map(p=>btn(p.name+' — виж ограниченията','flora-product','doc','secondary wide',`data-id="${p.id}" data-plant="${plant?.id||''}" data-issue="${i.id}"`)).join('')}`:'<p>Не е потвърдена подходяща употреба на включените препарати за тази комбинация. Изпълни първите мерки и потърси конкретна диагноза/агроном.</p>'}<div class="guide-sources">${floraLink(i.url,'Източник и примери за признаците — интернет')}</div>`)}
function openFloraProduct(id,plantId='',issueId=''){const p=FLORA_PRODUCTS.find(p=>p.id===id),plant=floraFind(plantId);if(!p)return;modal(p.name,`<p><strong>${esc(p.active)}</strong><br>Категория: ${esc(p.category)}</p><div class="notice"><strong>Обхват:</strong> ${esc(p.scope)}</div>${plant?`<p>Отворено за ${esc(plant.name)}. ${floraProductMatches(p,plant,issueId)?'Провери всички условия на точния етикет.':'Не е установена подходяща употреба за тази комбинация.'}</p>`:''}${p.uses.map(u=>`<section class="card flora-dose"><h3>${esc(u.target)}</h3><p><strong>Доза по площ:</strong> ${esc(u.dose)}</p><p><strong>Работен разтвор:</strong> ${esc(u.water)}</p><p><strong>Повторение:</strong> ${esc(u.limits)}</p></section>`).join('')}<h3>Начин на работа</h3><p>${esc(p.method)}</p><p>${esc(p.caution)}</p><p class="muted">1 дка = 1000 m². Количеството препарат се изчислява за реално покриваната площ. ${p.id==='ironmax'?'Гранулите се отмерват по площ и не се разреждат.':'Водата се определя чрез калибриране в допустимите граници; няма универсално „за 10 литра“.'}</p><div class="notice"><strong>Статус на проверката:</strong> ${esc(p.status)}</div><div class="guide-sources">${floraLink(p.url,'Български етикет / заповед — прочети пълния документ')}${floraLink(p.supplier,'Производител / дистрибутор и информация за покупка')}${floraLink(FLORA_REGISTRY,'Свери текущото разрешение в БАБХ')}</div>`)}
function setupFlora(){document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const id=el.dataset.id;switch(el.dataset.action){case'flora-topic':navPush();state.floraTopic=el.dataset.value;render();break;case'flora-plant':openFloraPlant(id);break;case'flora-issue':openFloraIssue(id,el.dataset.plant);break;case'flora-product':openFloraProduct(id,el.dataset.plant,el.dataset.issue);break;case'flora-work':{const p=floraFind(id);managerEditor('workLogs','',{name:'Грижа: '+p.name,steps:p.care.map(text=>({text,done:false})),notes:p.winter+(p.note?'\n'+p.note:'')});break}}});document.addEventListener('change',e=>{if(e.target.id==='flora-group'){state.floraGroup=e.target.value;render()}});document.addEventListener('input',e=>{const map={'flora-search':'floraSearch','issue-search':'issueSearch'},key=map[e.target.id];if(!key)return;const id=e.target.id,pos=e.target.selectionStart;state[key]=e.target.value;render();const input=$('#'+id);input.focus();input.setSelectionRange(pos,pos)});}
